'use strict';

/**
* Compute a one-parameter Box-Cox transformation for single-precision floating-point number.
*
* @module @stdlib/math/base/special/boxcoxf
*
* @example
* var boxcoxf = require( '@stdlib/math/base/special/boxcoxf' );
*
* var v = boxcoxf( 1.0, 2.5 );
* // returns 0.0
*
* v = boxcoxf( 4.0, 2.5 );
* // returns ~12.4
*
* v = boxcoxf( 10.0, 2.5 );
* // returns ~126.0911
*
* v = boxcoxf( 2.0, 0.0 );
* // returns ~0.6931
*
* v = boxcoxf( -1.0, 2.5 );
* // returns NaN
*
* v = boxcoxf( 0.0, -1.0 );
* // returns -Infinity
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
